INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (1, 'high_value', '高价值客户', '价值', '年消费 ≥ ¥50,000 或 LTV ≥ ¥8,000', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (2, 'price_sensitive', '价格敏感', '行为', '促销转化率高 · 均价低于门市价 15%', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (3, 'family', '亲子家庭', '画像', '历史携儿童订单 ≥ 2', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (4, 'business', '商务常旅客', '画像', '工作日入住占比 > 70%', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (5, 'complaint_risk', '投诉风险', '风险', '模型：Complaint_v2（置信度 > 80%）', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (6, 'douyin_fan', '抖音粉丝', '渠道', '抖音渠道订单 ≥ 1 或私域互动 ≥ 3', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (7, 'xhs_fan', '小红书种草', '渠道', '小红书来源订单 ≥ 1', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (8, 'repeat', '复购客', '忠诚度', '180 天内订单 ≥ 5', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (9, 'vip', 'VIP', '忠诚度', '会员等级 ∈ {金卡, 白金} 或累计间夜 ≥ 20', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (10, 'pref_quiet_high_floor', '偏好高层安静房', '画像', 'review:quiet AND pref:high_floor', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (11, 'active_90d', '近90天高活跃', '行为', 'stays>=2 AND ltv>3000 AND days<=90', true);
INSERT INTO public.tag_definitions (id, code, name, category, rule_expr, is_active) VALUES (12, 'iot_anomaly', 'IoT异常信号', '风险', 'event:iot_anomaly', true);
