INSERT INTO public.revenue_anomalies (id, hotel_id, code, category, title, subtitle, score, tone, description, detail_title, actor, room_label, event_time, orig_amount, new_amount, diff_label, timeline_json, ai_hint, status, created_at) VALUES (1, 1, 'ANM-8924', 'price', '未经审批的人工改价', '302 房间 • 前台 • John Doe', 92, 'high', 'AI 检测到一笔 45% 的人工折扣，超出标准促销窗口且缺少经理签字。', '人工改价', 'John Doe', '302 房间', '今日 14:32', 1200.00, 660.00, '-45%', '[{"tone": "primary", "title": "散客问询", "time": "14:15", "text": "John Doe 报出的标准价。"}, {"tone": "error", "title": "人工改写价格", "time": "14:32", "text": "价格由 ¥1,200 改为 ¥660，未输入管理审批码。"}, {"tone": "tertiary", "title": "AI 异常已触发", "time": "14:33", "text": "折扣超出散客标准额度（上限 15%），已标记以进行模式匹配。", "ai": true}]', '需经理立即干预或自动冲正交易。用户历史存在类似模式。', 'open', '2026-09-12 14:23:00.019626');
INSERT INTO public.revenue_anomalies (id, hotel_id, code, category, title, subtitle, score, tone, description, detail_title, actor, room_label, event_time, orig_amount, new_amount, diff_label, timeline_json, ai_hint, status, created_at) VALUES (2, 1, 'ANM-8911', 'price', '异常折扣模式', '多笔预订 • 周末群组', 68, 'mid', '同一操作员 48 小时内连续开出 6 笔 ≥25% 折扣，偏离历史基线。', '异常折扣模式', '周末群组', '多笔预订', '今日 11:08', 4800.00, 3360.00, '-30%', '[{"tone": "primary", "title": "群组预订创建", "time": "10:40", "text": "周末团队 8 间夜进入询价。"}, {"tone": "error", "title": "连续折扣开出", "time": "11:05", "text": "6 笔折扣均 ≥25%，且未关联有效促销活动。"}, {"tone": "tertiary", "title": "AI 模式告警", "time": "11:08", "text": "与该操作员近 30 日折扣分布显著偏离，已标记复核。", "ai": true}]', '建议抽查操作员权限与促销码使用记录，必要时临时收紧折扣上限。', 'open', '2026-09-12 14:23:00.019626');
INSERT INTO public.revenue_anomalies (id, hotel_id, code, category, title, subtitle, score, tone, description, detail_title, actor, room_label, event_time, orig_amount, new_amount, diff_label, timeline_json, ai_hint, status, created_at) VALUES (3, 1, 'ANM-8902', 'void', '作废交易异常', 'POS 终端 2 • 餐厅', 75, 'mid', '同一 POS 终端短时多次作废大额单，疑似套现或账实不符。', '作废交易异常', 'POS 终端 2', '餐厅', '今日 12:46', 2180.00, 0.00, '作废', '[{"tone": "primary", "title": "正餐结账", "time": "12:22", "text": "桌台 T12 开出 ¥2,180 账单。"}, {"tone": "error", "title": "交易作废", "time": "12:41", "text": "未输入主管密码即作废，金额原路退回。"}, {"tone": "tertiary", "title": "AI 异常已触发", "time": "12:46", "text": "该终端今日作废笔数已超阈值（3 笔）。", "ai": true}]', '建议核对当班收银录像与作废审批链，必要时锁定该终端。', 'open', '2026-09-12 14:23:00.019626');
INSERT INTO public.revenue_anomalies (id, hotel_id, code, category, title, subtitle, score, tone, description, detail_title, actor, room_label, event_time, orig_amount, new_amount, diff_label, timeline_json, ai_hint, status, created_at) VALUES (4, 1, 'ANM-8876', 'ota', 'OTA 佣金渗漏', 'Booking.com • 价格不符', 34, 'low', '渠道卖价低于 PMS 底价，可能导致佣金与净收双损。', 'OTA 佣金渗漏', 'Booking.com', '价格不符', '昨日 22:10', 980.00, 860.00, '-12%', '[{"tone": "primary", "title": "渠道房价同步", "time": "21:55", "text": "BAR ¥980 推送至 Booking.com。"}, {"tone": "error", "title": "卖价偏离", "time": "22:08", "text": "渠道展示价 ¥860，低于底价护栏。"}, {"tone": "tertiary", "title": "AI 渗漏提示", "time": "22:10", "text": "预估单间夜佣金与净收损失约 ¥45。", "ai": true}]', '建议核对渠道映射房价与 BAR，必要时暂停该房型推送。', 'open', '2026-09-12 14:23:00.019626');
