INSERT INTO public.wx_landing_templates (id, template_key, name, category, thumbnail, blocks_json, is_system) VALUES (1, 'tpl_bind', '单券领取（企微欢迎语）', 'bind', NULL, '[{"id": "b1", "type": "banner", "props": {"badge": "专属管家 · 扫码礼遇", "title": "填写手机号 领取优惠券", "subtitle": "提交后开通专属管家档案，优惠券可在本店房费使用。", "bg": "#0f3d2e"}}, {"id": "b2", "type": "coupon_card", "props": {"coupon_id": null, "bind_pool": true}}, {"id": "b3", "type": "form_phone", "props": {"label": "手机号", "placeholder": "请输入预订/入住手机号", "required": true}}, {"id": "b4", "type": "button", "props": {"text": "提交并领取优惠券", "action": "submit_bind"}}, {"id": "b5", "type": "text", "props": {"text": "提交后将绑定专属管家档案（OneID）。每份企微身份仅可领取一次。优惠券仅限本店房费使用。"}}]', true);
INSERT INTO public.wx_landing_templates (id, template_key, name, category, thumbnail, blocks_json, is_system) VALUES (2, 'tpl_member_center', '会员中心', 'member', NULL, '[{"id": "mc1", "type": "banner", "props": {"badge": "专属会员中心", "title": "我的会员中心", "subtitle": "查看私域优惠券、订单与会员权益"}}, {"id": "mc2", "type": "member_header", "props": {"show_stats": true}}, {"id": "mc3", "type": "nav_tabs", "props": {"tabs": [{"key": "coupon", "label": "我的券"}, {"key": "order", "label": "历史订单"}, {"key": "benefit", "label": "权益中心"}]}}, {"id": "mc4", "type": "coupon_wallet", "props": {"tab": "coupon", "title": "私域优惠券"}}, {"id": "mc5", "type": "order_list", "props": {"tab": "order", "title": "历史订单", "limit": 12}}, {"id": "mc6", "type": "benefit_list", "props": {"tab": "benefit", "title": "权益中心"}}, {"id": "mc7", "type": "text", "props": {"text": "本页由酒店装修发布。券仅限本店私域渠道发放，到店出示券码即可核销。"}}]', true);
